6090   * The returned value is always in normal form and is marked as trusted.
  6091   * A full, not floating, reference is returned.
  6092   *
  6093   * Returns: (transfer full): the byteswapped form of @value
  6094   *
  6095   * Since: 2.24
  6096   **/
  6097  GVariant *
  6098  g_variant_byteswap (GVariant *value)
  6099  {
  6100    GVariantTypeInfo *type_info;
  6101    guint alignment;
  6102    GVariant *new;
  6103
  6104    type_info = g_variant_get_type_info (value);
  6105
  6106    g_variant_type_info_query (type_info, &alignment, NULL);
  6107
  6108    if (alignment && g_variant_is_normal_form (value))
  6109      {
  6110        /* (potentially) contains multi-byte numeric data, but is also already in
  6111         * normal form so we can use a faster byteswapping codepath on the
  6112         * serialised data */
  6113        GVariantSerialised serialised = { 0, };
  6114        GBytes *bytes;
  6115
  6116        serialised.type_info = g_variant_get_type_info (value);
  6117        serialised.size = g_variant_get_size (value);
  6118        serialised.data = g_malloc (serialised.size);
  6119        serialised.depth = g_variant_get_depth (value);
  6120        serialised.ordered_offsets_up_to = G_MAXSIZE;  /* operating on the normal form */
  6121        serialised.checked_offsets_up_to = G_MAXSIZE;
  6122        g_variant_store (value, serialised.data);
  6123
  6124        g_variant_serialised_byteswap (serialised);
  6125
  6126        bytes = g_bytes_new_take (serialised.data, serialised.size);
  6127        new = g_variant_ref_sink (g_variant_new_from_bytes (g_variant_get_type (value), bytes, TRUE));
  6128        g_bytes_unref (bytes);
  6129      }
  6130    else if (alignment)
  6131      /* (potentially) contains multi-byte numeric data */
  6132      new = g_variant_ref_sink (g_variant_deep_copy (value, TRUE));
  6133    else
  6134      /* contains no multi-byte data */
  6135      new = g_variant_get_normal_form (value);

