    21  #include "fuzz.h"
    22
    23  int
    24  LLVMFuzzerTestOneInput (const unsigned char *data, size_t size)
    25  {
    26    GVariant *variant = NULL, *swapped_variant = NULL;
    27
    28    fuzz_set_logging_func ();
    29
    30    variant = g_variant_new_from_data (G_VARIANT_TYPE_VARIANT, data, size, FALSE,
    31                                       NULL, NULL);
    32    if (variant == NULL)
    33      return 0;
    34
    35    swapped_variant = g_variant_byteswap (variant);
    36    g_variant_get_data (swapped_variant);
    37
    38    g_variant_unref (swapped_variant);
    39    g_variant_unref (variant);
    40    return 0;
    41  }
